/bin/bash -lc "cat > /tmp/setup_lab_dns.py <<'PY'
from pathlib import Path
import re
zones=['.','com','net','edu','it','example.com','company.com','service.com','lab.net','tools.net','university.edu','campus.edu','unibo.it','comune.it','regione.it','shop.example.com','blog.example.com','dept.company.com','intranet.company.com','api.service.com','research.lab.net','ai.research.lab.net','data.research.lab.net','dev.lab.net','ci.tools.net','vpn.university.edu','courses.university.edu','portal.campus.edu','studenti.unibo.it','servizi.comune.it','dati.regione.it','org','io','gov','info','foundation.org','project.org','startup.io','platform.io','ministero.gov','news.info','archive.foundation.org','docs.project.org','api.startup.io','status.platform.io','open.ministero.gov','servizi.ministero.gov','local.news.info','media.news.info']
ips={i:re.search(r'inet (10\\.\\d+\\.\\d+\\.\\d+)/',Path(f'pc{i}.startup').read_text()).group(1) for i in range(1,61)}
servers={z:i for i,z in enumerate(zones,1)}
def fq(z): return z if z=='.' else z+'.'
def ns(z): return 'ns.root.' if z=='.' else 'ns.'+z+'.'
def parent(z): return z.split('.',1)[1] if '.' in z else '.'
for z,i in servers.items():
 d=Path(f'pc{i}/etc/bind'); d.mkdir(parents=True,exist_ok=True)
 lines=['"'$TTL 300'"',f'"'$ORIGIN {fq(z)}'"',f'@ IN SOA {ns(z)} hostmaster.{\"root.\" if z==\".\" else fq(z)} ( 2026110301 3600 600 604800 300 )',f'@ IN NS {ns(z)}',f'{ns(z)} IN A {ips[i]}']
 if z"'!='"'.': lines.append(f'@ IN A {ips[i]}')
 if z in ('company.com','university.edu','dept.company.com','servizi.ministero.gov'):
  lines.extend([f'@ IN MX 10 mail.{fq(z)}',f'mail IN A {ips[i]}'])
 for child,j in servers.items():
  if child"'!='"'.' and parent(child)==z:
   lines.extend([f'{fq(child)} IN NS {ns(child)}',f'{ns(child)} IN A {ips[j]}'])
 (d/'db.zone').write_text('\\n'.join(lines)+'\\n')
 (d/'named.conf').write_text(f'''options {{
    directory \"/tmp\";
    listen-on port 53 {{ any; }};
    listen-on-v6 {{ none; }};
    recursion no;
    allow-query {{ any; }};
    dnssec-validation no;
    pid-file \"/tmp/named.pid\";
}};
zone \"{z}\" {{ type primary; file \"/etc/bind/db.zone\"; }};
''')
d=Path('pc50/etc/bind'); d.mkdir(parents=True,exist_ok=True)
(d/'root.hints').write_text(f'. 300 IN NS ns.root.\\nns.root. 300 IN A {ips[1]}\\n')
(d/'named.conf').write_text('''options {
    directory \"/tmp\";
    listen-on port 53 { any; };
    listen-on-v6 { none; };
    recursion yes;
    allow-query { any; };
    allow-recursion { any; };
    allow-query-cache { any; };
    dnssec-validation no;
    empty-zones-enable no;
    pid-file \"/tmp/named.pid\";
};
zone \".\" { type hint; file \"/etc/bind/root.hints\"; };
''')
for i in range(1,61):
 p=Path(f'pc{i}.startup'); s=p.read_text(); s+='\\n# DNS: use the lab recursive resolver.\\nprintf \"nameserver %s\\\\n\" \"'+ips[50]+'\" > /etc/resolv.conf\\n'
 if i<=50: s+='\\n# Start the lab DNS server.\\nnamed -c /etc/bind/named.conf\\n'
 p.write_text(s)
print('zones',len(zones),'delegations',len(zones)-1,'resolver',ips[50])
PY
python3 /tmp/setup_lab_dns.py
command -v named-checkzone || true
command -v dig || true"

